for slug,(title,desc,body) in content.items():
 if slug==services[2][0]:
  body=body.replace('</aside>','<a href="../referenciak/#smp-eloszto">Kapcsolódó referencia: SMP Kecskemét <span aria-hidden="true">↗</span></a></aside>')
 pre='../' if slug else './';url='https://klelectro.hu/'+(slug+'/' if slug else '')
 nav=''.join(f'<a href="{pre}{path}/"'+(' aria-current="page"' if slug==path or (path=='szolgaltatasok' and slug in [v[0] for v in services]) else '')+f'>{label}</a>' for path,label in [('szolgaltatasok','Szolgáltatások'),('rolunk','Rólunk'),('referenciak','Referenciák')])
 graph=[org,{'@type':'WebSite','@id':'https://klelectro.hu/#website','url':'https://klelectro.hu/','name':'K-L Electro Kft.','inLanguage':'hu'},{'@type':'ContactPage' if slug=='kapcsolat' else 'CollectionPage' if slug=='referenciak' else 'WebPage','@id':url+'#page','url':url,'name':title,'description':desc,'inLanguage':'hu','isPartOf':{'@id':'https://klelectro.hu/#website'}}]
 banner=''
 if slug:
  crumbs=[{'@type':'ListItem','position':1,'name':'Főoldal','item':'https://klelectro.hu/'},{'@type':'ListItem','position':2,'name':labels[slug],'item':url}]
  graph.append({'@type':'BreadcrumbList','@id':url+'#breadcrumb','itemListElement':crumbs});graph[2]['breadcrumb']={'@id':url+'#breadcrumb'}
  if slug in [v[0] for v in services]:graph.append({'@type':'Service','name':labels[slug],'url':url,'provider':{'@id':org['@id']}})
  banner=f'<section class="page-banner"><div class="container"><nav class="breadcrumb" aria-label="Morzsanavigáció"><a href="{pre}">Főoldal</a><span aria-hidden="true">/</span><span aria-current="page">{labels[slug]}</span></nav><h1>{labels[slug]}</h1><p>{desc.split(" K-L Electro")[0]}</p></div></section>'
 document=f'''<!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title}</title><meta name="description" content="{html.escape(desc)}"><meta name="robots" content="index, follow, max-image-preview:large"><link rel="canonical" href="{url}"><meta name="theme-color" content="#284399"><meta property="og:type" content="website"><meta property="og:locale" content="hu_HU"><meta property="og:site_name" content="K-L Electro Kft."><meta property="og:title" content="{title}"><meta property="og:description" content="{html.escape(desc)}"><meta property="og:url" content="{url}"><meta property="og:image" content="https://klelectro.hu/assets/brand/logo.png"><meta property="og:image:alt" content="K-L Electro"><meta name="twitter:card" content="summary"><link rel="icon" href="{pre}assets/brand/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{pre}assets/css/blue.css"><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False)}</script><script defer src="{pre}assets/js/blue.js"></script></head><body><a class="skip-link" href="#content">Ugrás a tartalomhoz</a><div class="topline"><div class="container"><span>Villamosipari megoldások 2002 óta</span><a href="tel:+36703831532">+36 (70) 383 15 32</a></div></div><header class="site-header"><div class="container header-inner"><a class="brand" href="{pre}" aria-label="K-L Electro – Főoldal"><img src="{pre}assets/brand/logo.webp" width="1000" height="120" alt="K-L Electro" fetchpriority="high"></a><button class="nav-toggle" type="button" aria-label="Menü megnyitása" aria-expanded="false" aria-controls="primary-navigation"><span></span><span></span></button><nav id="primary-navigation" aria-label="Fő navigáció">{nav}{link(pre+'kapcsolat/','Kapcsolat','button nav-contact')}</nav></div></header><main id="content">{banner}{body}</main><footer><div class="container footer-grid"><div><a class="brand footer-brand" href="{pre}"><img src="{pre}assets/brand/logo.webp" width="1000" height="120" alt="K-L Electro"></a><p>Villamos kivitelezés.<br>Biztos alapokon, 2002 óta.</p></div><div><h2>Fedezze fel</h2>{nav}<a href="{pre}palyazatok/">Pályázatok</a><a href="{pre}kapcsolat/">Kapcsolat</a></div><div><h2>Elérhetőségeink</h2><a href="tel:+36703831532">+36 (70) 383 15 32</a><a href="tel:+36703831489">+36 (70) 383 14 89</a><a href="mailto:arajanlat@klelectro.hu">arajanlat@klelectro.hu</a><p>H–P: 07:00–16:00</p></div><div><h2>Itt talál minket</h2><address>Székhely: 3900 Szerencs, Árpád köz 8.<br><br>Telephely: 4121 Szentpéterszeg, Dobó utca 1.</address></div></div><div class="container footer-bottom"><span>© 2026 K-L Electro Kft.</span><span>Gyártás · Kivitelezés · Diagnosztika</span></div></footer></body></html>'''
 if not PRODUCTION:document=document.replace('index, follow, max-image-preview:large','noindex, follow, max-image-preview:large')
 path=ROOT/slug/'index.html' if slug else ROOT/'index.html'
 path.parent.mkdir(parents=True,exist_ok=True);path.write_text(document,encoding='utf-8')
# Keep the deployable production directory separate from the GitHub demo.
if PRODUCTION:
 shutil.copytree(SOURCE/'assets',ROOT/'assets',dirs_exist_ok=True)
 shutil.copyfile(DATA/'production.htaccess',ROOT/'.htaccess')
 error=(SOURCE/'404.html').read_text(encoding='utf-8').replace('/klelectrodemo/','/')
 (ROOT/'404.html').write_text(error,encoding='utf-8')
(ROOT/'.nojekyll').write_text('',encoding='utf-8')
